CREATE TABLE [dbo].[ccHorarios](	  [horario_id] SMALLINT NOT NULL IDENTITY(1,1)	, [Descripcion] VARCHAR(40) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [HoraInicio] TINYINT NOT NULL DEFAULT((9))	, [MinInicio] TINYINT NOT NULL DEFAULT((0))	, [HoraFin] TINYINT NOT NULL DEFAULT((18))	, [MinFin] TINYINT NOT NULL DEFAULT((0))	, [Lunes] BIT NOT NULL DEFAULT((1))	, [Martes] BIT NOT NULL DEFAULT((1))	, [Miercoles] BIT NOT NULL DEFAULT((1))	, [Jueves] BIT NOT NULL DEFAULT((1))	, [Viernes] BIT NOT NULL DEFAULT((1))	, [Sabado] BIT NOT NULL DEFAULT((1))	, [Domingo] BIT NOT NULL DEFAULT((1))	, CONSTRAINT [PK_ccHorarios] PRIMARY KEY ([horario_id] ASC))